import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BGlkWkwp.js";const u=JSON.parse('{"title":"NativeSelect","description":"","frontmatter":{},"headers":[],"relativePath":"components/native-select.md","filePath":"components/native-select.md"}'),n={name:"components/native-select.md"};function r(i,e,c,s,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="nativeselect" tabindex="-1">NativeSelect <a class="header-anchor" href="#nativeselect" aria-label="Permalink to &quot;NativeSelect&quot;">​</a></h1><p>NativeSelect is a select that opens the browser&#39;s own list.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for long lists (languages, time zones) and on phones. <code>groups</code> puts options under headings; an option can be <code>disabled</code> to show that it cannot be chosen now. <code>placeholder</code> adds a first line while nothing is chosen. For options with a description use a <a href="./select">Select</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>options</code></td><td><code>[]</code></td><td><code>{ value, label, disabled? }[]</code></td></tr><tr><td><code>groups</code></td><td></td><td><code>{ label, options }[]</code>, shown before <code>options</code></td></tr><tr><td><code>value</code></td><td></td><td>The chosen value (bindable)</td></tr><tr><td><code>placeholder</code></td><td></td><td>The first line while nothing is chosen</td></tr><tr><td><code>ariaLabel</code></td><td></td><td>The accessible name without a Field</td></tr><tr><td><code>id</code></td><td></td><td>The id of the select</td></tr><tr><td><code>error</code></td><td><code>false</code></td><td>The line turns red</td></tr><tr><td><code>disabled</code></td><td><code>false</code></td><td>Cannot be changed</td></tr><tr><td><code>onchange</code></td><td></td><td>Called with the chosen value</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The control is a <code>&lt;label&gt;</code> of the height its container declares, with one line in line-strong, pad-md at the sides and a chevron on the right; the select inside is transparent. Focus turns the line blue-ink. While the placeholder shows, the text is faint. The list takes the panel color.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/native-select/" title="NativeSelect" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/native-select/" target="_blank" rel="noopener">NativeSelect</a></figcaption></figure>',10)])])}const b=t(n,[["render",r]]);export{u as __pageData,b as default};
